mapper.select:


  e.del_flag='0' and e.status='0'
  and e.del_flag='0' and e.status=#{status}
  and e.del_flag!='0'
  and e.category=#{category}
  and (e.title like concat('%',#{keyword},'%') or e.subtitle like concat('%',#{keyword},'%') or e.place_name like concat('%',#{keyword},'%'))

order by e.display_sort asc,e.published_at desc,e.enjoy_id desc
